void mainImage(out vec4 fragColor, in vec2 fragCoord){
    float time = iTime+3000.0;
    vec3 color;
    vec2 uv = gl_FragCoord.xy/iResolution.xy;
    uv.y *= sin(0.004)*-time+cos(time*uv.x +0.5);
    uv.x = 0.004*time/(170.0*sin(time-uv.y+0.5));
	color.r =-uv.x/3.0*sin( mod(time*.01 , 3.14159) );
	color.b = -uv.y/cos(pow(-time , 3.14159*(sin(time*30.0))));
	color.b = sin(mod((uv.y/uv.x),mod(2.0,uv.x)));
	uv.x =sin(time*3.14159);
    fragColor = vec4(color,1.0);
}
